// Имена компонентов/пропсов Jinx UI приведены по умолчанию — сверьте с вашей версией @jinx-ui/react.
import { useCallback, useState } from 'react';
import {
  Badge,
  Divider,
  Field,
  Heading,
  SegmentedControl,
  Select,
  Slider,
  Stack,
  Switch,
  Text,
} from '@jinx-ui/react';

export type ThemeMode = 'light' | 'dark' | 'system';
export type FontFamily = 'system' | 'inter' | 'mono';

export interface AppearanceSettings {
  theme: ThemeMode;
  scale: number;
  dense: boolean;
  font: FontFamily;
}

export interface AppearanceSettingsScreenProps {
  value?: Partial<AppearanceSettings>;
  onChange?: (next: AppearanceSettings) => void;
}

const DEFAULTS: AppearanceSettings = {
  theme: 'system',
  scale: 100,
  dense: false,
  font: 'system',
};

const THEME_OPTIONS: { value: ThemeMode; label: string }[] = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const FONT_OPTIONS: { value: FontFamily; label: string }[] = [
  { value: 'system', label: 'Системный' },
  { value: 'inter', label: 'Inter' },
  { value: 'mono', label: 'Моноширинный' },
];

function AppearanceSettingsScreen({ value, onChange }: AppearanceSettingsScreenProps) {
  const [settings, setSettings] = useState<AppearanceSettings>({ ...DEFAULTS, ...value });

  const patch = useCallback(
    (part: Partial<AppearanceSettings>) => {
      setSettings((prev) => {
        const next = { ...prev, ...part };
        onChange?.(next);
        return next;
      });
    },
    [onChange],
  );

  const themeLabel = THEME_OPTIONS.find((o) => o.value === settings.theme)?.label ?? '';

  return (
    <Stack direction="column" style={{ gap: 'var(--jx-space-6)', padding: 'var(--jx-space-6)' }}>
      <Stack direction="row" align="center" justify="between" style={{ gap: 'var(--jx-space-3)' }}>
        <Heading level={2}>Внешний вид</Heading>
        <Badge tone="neutral">{themeLabel}</Badge>
      </Stack>

      <Stack direction="column" style={{ gap: 'var(--jx-space-5)' }}>
        <Field label="Тема" description="Применяется ко всему интерфейсу">
          <SegmentedControl
            value={settings.theme}
            onChange={(theme: ThemeMode) => patch({ theme })}
            options={THEME_OPTIONS}
          />
        </Field>

        <Field label="Масштаб интерфейса">
          <Stack direction="row" align="center" style={{ gap: 'var(--jx-space-4)' }}>
            <Slider
              min={80}
              max={140}
              step={5}
              value={settings.scale}
              onChange={(scale: number) => patch({ scale })}
              aria-label="Масштаб интерфейса"
              style={{ flex: 1 }}
            />
            <Text variant="body" tone="muted" style={{ minWidth: 'var(--jx-size-12)' }}>
              {settings.scale}%
            </Text>
          </Stack>
        </Field>

        <Field label="Плотная вёрстка" description="Меньше отступов, больше данных на экране">
          <Switch checked={settings.dense} onChange={(dense: boolean) => patch({ dense })} />
        </Field>
      </Stack>

      <Divider />

      <Stack direction="column" style={{ gap: 'var(--jx-space-4)' }}>
        <Heading level={3}>Ещё</Heading>
        <Field label="Шрифт">
          <Select
            value={settings.font}
            onChange={(font: FontFamily) => patch({ font })}
            options={FONT_OPTIONS}
          />
        </Field>
      </Stack>
    </Stack>
  );
}

export default AppearanceSettingsScreen;

